# ── dry run? ────────────────────────────────────────────────────────
if [[ "${NORKHIZ_ONLY_FILES:-0}" == "1" ]]; then
  ok "Files extracted (NORKHIZ_ONLY_FILES=1 — install skipped)."
  exit 0
fi

# ── optional: import runtime data when moving to a new server ───────
# Create the archive on the OLD server from its app directory:
#   tar -czf /root/vortexnet-data.tar.gz server/data server/.env
# Copy it directly to the NEW server (never through chat/public links),
# then run this setup with VORTEXNET_DATA_ARCHIVE=/root/vortexnet-data.tar.gz.
DATA_ARCHIVE="${VORTEXNET_DATA_ARCHIVE:-${NORKHIZ_DATA_ARCHIVE:-}}"
if [[ -n "$DATA_ARCHIVE" ]]; then
  [[ -f "$DATA_ARCHIVE" ]] || die "Data archive not found: $DATA_ARCHIVE"
  log "Importing existing shop data from ${DATA_ARCHIVE}…"
  mkdir -p server/data
  if ! tar -xzf "$DATA_ARCHIVE" -C "$APP_DIR" --no-same-owner --no-same-permissions server/data server/.env 2>/dev/null; then
    tar -xzf "$DATA_ARCHIVE" -C "$APP_DIR" --no-same-owner --no-same-permissions server/data \
      || die "Could not import server/data from: $DATA_ARCHIVE"
  fi
  chmod 700 server/data 2>/dev/null || true
  find server/data -type f -exec chmod 600 {} + 2>/dev/null || true
  [[ -f server/.env ]] && chmod 600 server/.env 2>/dev/null || true
  ok "Existing shop data imported (users, orders, chats, sessions and settings preserved)"
fi

# ── make sure the frontend deps are declared ────────────────────────
HAVE_NODE=0; command -v node >/dev/null 2>&1 && HAVE_NODE=1
[[ "$HAVE_NODE" == "1" ]] || log "Node.js not found yet — the installer will set it up."
if [[ "$HAVE_NODE" == "1" ]] && ! grep -q '"@fontsource/vazirmatn"' package.json; then
  log "Adding local Persian fonts (Vazirmatn, Space Grotesk)…"
  npm i -S @fontsource/vazirmatn @fontsource/space-grotesk
fi
if [[ "$HAVE_NODE" == "1" ]] && ! grep -q '"qrcode-generator"' package.json; then
  log "Adding QR library for subscription links…"
  npm i -S qrcode-generator@1.4.4
fi

# ── don't let env files leak dev settings into the production build ─
for f in .env .env.local; do
  if [[ -f "$f" ]] && grep -Eq '^(VITE_BASE|BASE_PATH)=' "$f"; then
    sed -i.bak -E '/^(VITE_BASE|BASE_PATH)=/d' "$f"
    warn "Removed VITE_BASE/BASE_PATH from $f (production must use /). Backup: $f.bak"
  fi
done
unset VITE_BASE BASE_PATH

chmod +x install.sh update.sh

# ── run the full installer (build → /var/www/aether → Nginx /api proxy
#    → shop API systemd service → firewall → health check) ──────────
ARGS=()
[[ -n "$DOMAIN" ]] && ARGS+=(--domain "$DOMAIN")
[[ -n "$SSL_EMAIL" ]] && ARGS+=(--ssl "$SSL_EMAIL")
log "Running installer (این مرحله ممکن است ۱ تا ۳ دقیقه طول بکشد)…"
API_PORT="$API_PORT" bash install.sh "${ARGS[@]}"

PUBLIC_IP="$(curl -fsS --max-time 4 https://api.ipify.org 2>/dev/null || echo '<SERVER-IP>')"
DISPLAY_DOMAIN="$DOMAIN"
if [[ -z "$DISPLAY_DOMAIN" && -f server/.env ]]; then
  DISPLAY_DOMAIN="$(grep -E '^SITE_DOMAIN=' server/.env | tail -1 | cut -d= -f2 | tr -d ' \"'\''\r' || true)"
fi
if [[ -n "$DISPLAY_DOMAIN" && -d "/etc/letsencrypt/live/${DISPLAY_DOMAIN}" ]]; then
  SITE_URL="https://${DISPLAY_DOMAIN}/"
elif [[ -n "$DISPLAY_DOMAIN" ]]; then
  SITE_URL="http://${DISPLAY_DOMAIN}/"
else
  SITE_URL="http://${PUBLIC_IP}/"
fi
echo
ok "ورتکس‌نت نصب/به‌روز شد 🎉 (حساب کاربری + سفارشات + سرویس من + چت پشتیبانی)"
echo "${c_dim}سایت:        ${SITE_URL}${c_reset}"
echo "${c_dim}پنل مدیریت:  http://${PUBLIC_IP}:${API_PORT}  — بخش «💬 چت‌ها» برای گفت‌وگو با مشتری${c_reset}"
